-- 지역→공항 노선 201~207을 운영사 공식 시간표(2026-11-03 조회)로 교체한다. V100의 추정값을 대체한다.
-- 분은 운행일 기준이며 자정 넘김 편은 없다. SATURDAY와 HOLIDAY는 같은 목록이다(운영사가 토·휴일을 한 표로 제공).
-- 203은 요일 구분이 없는 단일 시각표라 세 유형 모두 같다.
-- duration_min은 낙관적이지 않도록 시각표에서 관측한 최대 소요를 쓴다(201·202는 note 참조). 요금·도보·택시는 바꾸지 않는다.

UPDATE transport_route SET
    duration_min = 38,
    schedule_type = 'TIMETABLE',
    first_departure_min = NULL, last_departure_min = NULL, headway_min = NULL,
    note = '공식 시간표 기준(난카이, 2026-11-03 조회). 기준일 표기 2024/12/21로 개정 반영 확인 필요. 소요 38분은 보수값(공식 최단 34분). 요금·도보는 추정, 공식 확인 필요',
    source_url = 'https://kensaku.nankai.co.jp/pc/T5?USR=PC&slCode=306-0&d=1&dw=0',
    data_as_of = '2026-11-03'
WHERE id = 201;

UPDATE transport_route SET
    duration_min = 45,
    schedule_type = 'TIMETABLE',
    first_departure_min = NULL, last_departure_min = NULL, headway_min = NULL,
    note = '공식 시간표 기준(난카이, 2026-11-03 조회). 기준일 표기 2024/12/21로 개정 반영 확인 필요. 소요 45분은 공식 안내값. 요금·도보는 추정, 공식 확인 필요',
    source_url = 'https://kensaku.nankai.co.jp/pc/T5?USR=PC&slCode=306-0&d=1&dw=0',
    data_as_of = '2026-11-03'
WHERE id = 202;

UPDATE transport_route SET
    duration_min = 67,
    board_stop = '한큐산방가이 버스 정류장 (오사카역 앞)',
    schedule_type = 'TIMETABLE',
    first_departure_min = NULL, last_departure_min = NULL, headway_min = NULL,
    note = '공식 시간표 기준(KATE, 2026-11-03 조회, 요일 구분 없음). 소요 67분은 시각표 최대값(평균 59분, 도로 정체 미반영). 요금·도보는 추정, 공식 확인 필요',
    source_url = 'https://www.kate.co.jp/timetable/detail/UM',
    data_as_of = '2026-11-03'
WHERE id = 203;

UPDATE transport_route SET
    duration_min = 79,
